    TOPICS2 = Object.freeze({ "schemaVersion": "PHI-OS-ECR-TOPIC-REGISTRY-v1.0.0", "work": "ECR-TOPIC-R1-W4-W9", "status": "CANDIDATE_TOPIC_PROJECTION_AUTHORITY", "topics": [{ "topicId": "CAREER", "label": "Career & Work", "labelZhHans": "\u4E8B\u4E1A\u4E0E\u5DE5\u4F5C", "purpose": "Read direction, position, resources, execution, structure and change only where the current ECR configuration already carries those owners.", "purposeZhHans": "\u53EA\u5728\u5F53\u524D ECR \u6784\u578B\u5DF2\u547D\u4E2D\u7684\u8BED\u4E49 owner \u4E2D\uFF0C\u8BFB\u53D6\u65B9\u5411\u3001\u4F4D\u7F6E\u3001\u8D44\u6E90\u3001\u6267\u884C\u3001\u7ED3\u6784\u4E0E\u53D8\u5316\u3002", "preview": "Work becomes useful to read through the parts of this configuration that organize direction, role, resources and execution.", "previewZhHans": "\u4E8B\u4E1A\u4E3B\u9898\u53EA\u4ECE\u5F53\u524D\u6784\u578B\u5DF2\u7ECF\u51FA\u73B0\u7684\u65B9\u5411\u3001\u89D2\u8272\u3001\u8D44\u6E90\u4E0E\u6267\u884C\u7ED3\u6784\u8FDB\u5165\u3002", "realityQuestion": "In your current work situation, what is actually limiting movement: direction, position, resources, execution, or the surrounding structure?", "realityQuestionZhHans": "\u5728\u5F53\u524D\u5DE5\u4F5C\u73B0\u5B9E\u91CC\uFF0C\u771F\u6B63\u9650\u5236\u63A8\u8FDB\u7684\u66F4\u50CF\u662F\u65B9\u5411\u3001\u4F4D\u7F6E\u3001\u8D44\u6E90\u3001\u6267\u884C\uFF0C\u8FD8\u662F\u5468\u56F4\u7ED3\u6784\uFF1F" }, { "topicId": "RELATIONSHIP", "label": "Relationship", "labelZhHans": "\u5173\u7CFB", "purpose": "Read difference, response, shared carrying and relational coordination without producing a compatibility verdict.", "purposeZhHans": "\u8BFB\u53D6\u5DEE\u5F02\u3001\u56DE\u5E94\u3001\u5171\u540C\u627F\u8F7D\u4E0E\u5173\u7CFB\u534F\u8C03\uFF0C\u4E0D\u4EA7\u751F\u5408\u4E0D\u5408\u6216\u76F8\u5BB9\u5EA6\u7ED3\u8BBA\u3002", "preview": "Relationship is read through the parts of this configuration that organize response to another reality and shared structure.", "previewZhHans": "\u5173\u7CFB\u4E3B\u9898\u4ECE\u5F53\u524D\u6784\u578B\u4E2D\u5982\u4F55\u56DE\u5E94\u53E6\u4E00\u4E2A\u73B0\u5B9E\u3001\u5982\u4F55\u7EC4\u7EC7\u5171\u540C\u7ED3\u6784\u8FDB\u5165\u3002", "realityQuestion": "When difference appears in an important relationship, what happens next in reality: understanding, expression, repositioning, shared carrying, or withdrawal?", "realityQuestionZhHans": "\u91CD\u8981\u5173\u7CFB\u51FA\u73B0\u5DEE\u5F02\u65F6\uFF0C\u73B0\u5B9E\u4E2D\u63A5\u4E0B\u6765\u901A\u5E38\u53D1\u751F\u4EC0\u4E48\uFF1A\u7406\u89E3\u3001\u8868\u8FBE\u3001\u91CD\u65B0\u5B9A\u4F4D\u3001\u5171\u540C\u627F\u8F7D\uFF0C\u8FD8\u662F\u9000\u51FA\uFF1F" }, { "topicId": "RESOURCES", "label": "Resources & Money", "labelZhHans": "\u8D44\u6E90\u4E0E\u91D1\u94B1", "purpose": "Read available resources, exchange capacity, sustaining inputs and execution without predicting wealth or return.", "purposeZhHans": "\u8BFB\u53D6\u53EF\u7528\u8D44\u6E90\u3001\u4EA4\u6362\u80FD\u529B\u3001\u6301\u7EED\u8F93\u5165\u4E0E\u6267\u884C\uFF0C\u4E0D\u9884\u6D4B\u8D22\u5BCC\u6216\u56DE\u62A5\u3002", "preview": "Resources are read as what can be accessed, exchanged, sustained and converted into operation\u2014not as a wealth prediction.", "previewZhHans": "\u8D44\u6E90\u4E3B\u9898\u8BFB\u53D6\u4EC0\u4E48\u53EF\u4EE5\u88AB\u53D6\u5F97\u3001\u4EA4\u6362\u3001\u7EF4\u6301\u5E76\u8F6C\u5316\u4E3A\u8FD0\u884C\uFF0C\u800C\u4E0D\u662F\u8D22\u5BCC\u9884\u6D4B\u3002", "realityQuestion": "Which resource is actually scarce or constrained right now: time, money, attention, support, capacity, or execution?", "realityQuestionZhHans": "\u73B0\u5728\u771F\u6B63\u7A00\u7F3A\u6216\u53D7\u9650\u7684\u8D44\u6E90\u662F\u4EC0\u4E48\uFF1A\u65F6\u95F4\u3001\u91D1\u94B1\u3001\u6CE8\u610F\u529B\u3001\u652F\u6301\u3001\u5BB9\u91CF\uFF0C\u8FD8\u662F\u6267\u884C\u80FD\u529B\uFF1F" }, { "topicId": "FAMILY", "label": "Family & Shared Structure", "labelZhHans": "\u5BB6\u5EAD\u4E0E\u5171\u540C\u7ED3\u6784", "purpose": "Read roles, shared resources, carrying, stability and continuation inside a shared structure.", "purposeZhHans": "\u8BFB\u53D6\u5171\u540C\u7ED3\u6784\u4E2D\u7684\u89D2\u8272\u3001\u5171\u4EAB\u8D44\u6E90\u3001\u627F\u8F7D\u3001\u7A33\u5B9A\u4E0E\u6301\u7EED\u3002", "preview": "Family is read as a shared operating structure: who carries what, how stability is maintained, and where reorganization may be needed.", "previewZhHans": "\u5BB6\u5EAD\u4E3B\u9898\u88AB\u89C6\u4E3A\u5171\u540C\u8FD0\u884C\u7ED3\u6784\uFF1A\u8C01\u627F\u8F7D\u4EC0\u4E48\u3001\u7A33\u5B9A\u5982\u4F55\u7EF4\u6301\uFF0C\u4EE5\u53CA\u54EA\u91CC\u53EF\u80FD\u9700\u8981\u91CD\u7EC4\u3002", "realityQuestion": "What part of the family structure is being maintained by habit, role or unequal carrying rather than by current agreement?", "realityQuestionZhHans": "\u76EE\u524D\u5BB6\u5EAD\u7ED3\u6784\u4E2D\uFF0C\u54EA\u4E00\u90E8\u5206\u4E3B\u8981\u9760\u4E60\u60EF\u3001\u89D2\u8272\u6216\u4E0D\u5747\u8861\u627F\u8F7D\u7EF4\u6301\uFF0C\u800C\u4E0D\u662F\u5F53\u524D\u5171\u540C\u8BA4\u540C\uFF1F" }, { "topicId": "SELF_DIRECTION", "label": "Self & Direction", "labelZhHans": "\u81EA\u6211\u4E0E\u65B9\u5411", "purpose": "Read orientation, understanding, expression, agency and position without turning ECR into a personality type.", "purposeZhHans": "\u8BFB\u53D6\u65B9\u5411\u3001\u7406\u89E3\u3001\u8868\u8FBE\u3001\u884C\u52A8\u4E0E\u4F4D\u7F6E\uFF0C\u4E0D\u628A ECR \u53D8\u6210\u4EBA\u683C\u7C7B\u578B\u3002", "preview": "Self & Direction asks how this configuration organizes orientation and action, not what fixed type of person you are.", "previewZhHans": "\u81EA\u6211\u4E0E\u65B9\u5411\u5173\u6CE8\u5F53\u524D\u6784\u578B\u5982\u4F55\u7EC4\u7EC7\u65B9\u5411\u4E0E\u884C\u52A8\uFF0C\u800C\u4E0D\u662F\u628A\u4F60\u5F52\u7C7B\u6210\u56FA\u5B9A\u4EBA\u683C\u3002", "realityQuestion": "Where do you currently feel the largest gap between what you understand, what you express, and what you actually do?", "realityQuestionZhHans": "\u76EE\u524D\u4F60\u5728\u201C\u7406\u89E3\u4EC0\u4E48\u3001\u8868\u8FBE\u4EC0\u4E48\u3001\u5B9E\u9645\u505A\u4EC0\u4E48\u201D\u4E4B\u95F4\uFF0C\u6700\u5927\u7684\u843D\u5DEE\u5728\u54EA\u91CC\uFF1F" }, { "topicId": "TIMING_CHANGE", "label": "Timing & Change", "labelZhHans": "\u65F6\u95F4\u4E0E\u53D8\u5316", "purpose": "Read how the current motion and activation stages shape change around an already-selected ECR configuration.", "purposeZhHans": "\u8BFB\u53D6\u5F53\u524D\u8FD0\u52A8\u4E0E\u6FC0\u6D3B\u9636\u6BB5\u5982\u4F55\u5F71\u54CD\u5DF2\u7ECF\u9009\u5B9A\u7684 ECR \u6784\u578B\u53D8\u5316\u3002", "preview": "Timing does not predict an outcome; it shows how change is currently entering, gaining weight, amplifying, aligning, decaying or closing.", "previewZhHans": "\u65F6\u95F4\u4E3B\u9898\u4E0D\u9884\u6D4B\u7ED3\u679C\uFF0C\u800C\u662F\u663E\u793A\u53D8\u5316\u76EE\u524D\u5982\u4F55\u8FDB\u5165\u3001\u589E\u91CD\u3001\u653E\u5927\u3001\u5BF9\u9F50\u3001\u8870\u9000\u6216\u95ED\u5408\u3002", "realityQuestion": "What has recently become easier to start, harder to sustain, more amplified, or closer to closure in lived reality?", "realityQuestionZhHans": "\u73B0\u5B9E\u4E2D\u6700\u8FD1\u6709\u4EC0\u4E48\u53D8\u5F97\u66F4\u5BB9\u6613\u542F\u52A8\u3001\u66F4\u96BE\u7EF4\u6301\u3001\u88AB\u660E\u663E\u653E\u5927\uFF0C\u6216\u66F4\u63A5\u8FD1\u7ED3\u675F\uFF1F" }] });
